import{_ as t,o,c as a,ag as i}from"./chunks/framework.CVaJrGn7.js";const u=JSON.parse('{"title":"@guideflow/mcp","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/packages/mcp"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/packages/mcp"}],["meta",{"property":"og:title","content":"@guideflow/mcp — GuideFlow.js"}],["meta",{"property":"og:description","content":"AI-powered product tours. Guide users like you know them. Open-source tour library for React, Vue, Svelte & Vanilla JS."}],["meta",{"name":"twitter:title","content":"@guideflow/mcp — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"AI-powered product tours. Guide users like you know them. Open-source tour library for React, Vue, Svelte & Vanilla JS."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Packages\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Mcp\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/mcp/\\"}]}"]]},"headers":[],"relativePath":"packages/mcp.md","filePath":"packages/mcp.md","lastUpdated":1786207781000}'),d={name:"packages/mcp.md"};function r(s,e,n,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="guideflow-mcp" tabindex="-1">@guideflow/mcp <a class="header-anchor" href="#guideflow-mcp" aria-label="Permalink to &quot;@guideflow/mcp&quot;">​</a></h1><p>MCP server. Guide: <a href="/GuideFlow/guide/mcp">MCP server</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/mcp</span></span></code></pre></div><p>Ships a <code>guideflow-mcp</code> binary that speaks MCP over <strong>stdio</strong>. Not HTTP: it reads the operator&#39;s own filesystem, so it belongs in the operator&#39;s own process rather than behind a port anything on the machine could reach.</p><p>Unlike every other package here, <code>@guideflow/core</code> is a real <strong>dependency</strong> rather than a peer — this is an application, not a library, and there is no host bundle for a peer to deduplicate against.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>--root &lt;dir&gt;</code></td><td>Directory every file read is scoped to</td></tr><tr><td><code>GUIDEFLOW_ROOT</code></td><td>Same, as an environment variable</td></tr><tr><td><em>(neither)</em></td><td>The working directory the client launched the server in</td></tr><tr><td><code>--version</code>, <code>--help</code></td><td>Print and exit</td></tr></tbody></table><p>The root is chosen by the <strong>operator</strong>, never by a tool argument — that is the whole security model. See the guide.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>All four are <code>readOnlyHint: true</code> and <code>destructiveHint: false</code>. Nothing writes a file.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Arguments</th></tr></thead><tbody><tr><td><code>guideflow_list_flows</code></td><td><code>limit</code> (1-200, default 50), <code>offset</code></td></tr><tr><td><code>guideflow_get_flow</code></td><td>exactly one of <code>path</code> or <code>flowId</code></td></tr><tr><td><code>guideflow_validate_flow</code></td><td><code>flow</code> — a <code>FlowDefinition</code> or a <code>{ gfFlowFile, flow }</code> envelope</td></tr><tr><td><code>guideflow_author_flow</code></td><td><code>id</code>, <code>name</code>, <code>steps[]</code>, <code>sourceUrl?</code></td></tr></tbody></table><p>Every tool returns <code>structuredContent</code> alongside a JSON text block, so clients that render only text still show something useful.</p><p>Errors come back as <code>isError</code> results with a message naming the next step — not as transport exceptions — because that is what the model actually sees.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><p>The version in the MCP handshake is substituted from <code>package.json</code> at build time via tsup&#39;s <code>define</code>, so it cannot drift from what changesets published. The same arrangement <code>@guideflow/devtools</code> uses for its extension manifest.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/GuideFlow/packages/cli">@guideflow/cli</a> — <code>guideflow validate</code>, the same validator on the command line</li><li><a href="/GuideFlow/packages/core">@guideflow/core</a> — <code>./authoring</code>, where the rules live</li></ul>',17)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
